from fractions import Fraction as Fr

def cand():
    out = set()
    e = Fr(1, 10**6)
    for al2 in range(-30, 41):
        for be2 in range(-30, 41):
            al, be = Fr(al2, 2), Fr(be2, 2)
            if al == be:
                continue
            def h(t):
                fv = (t - al)**2*(t - be)
                return (fv if fv >= 0 else 2*fv) + 8*abs(t - 3)
            ok = True
            for a in {al, be, Fr(3)}:
                sl = (h(a + e) - h(a))/e
                sr = (h(a) - h(a - e))/e
                if abs(sl - sr) > Fr(1, 100):
                    ok = False
                    break
            if ok:
                out.add(-(al**2)*be)
    return out

def skill():
    vals = [-3*al**2 for al in (-1, 7) if (3 - al)**2 == 16]
    return max(vals)*min(vals)

def standard():
    v = cand()
    return max(v)*min(v)

def unique():
    return [standard()]
